// ---------------------------------------------------------------- 4. 무라사 하늘거주지 — 2020년 이후에만 (RISEN)
/** 떠 있는 조각 — 위에서 비스듬히 본 윗면(타원)과 앞의 깎은 석회암 띠, 깨져 뾰족한 밑. (cx, cy) 윗면 가운데, w 너비 */
function chunk(cx, cy, w, seed, o = {}) {
  const r = rng(seed)
  const ry = w * (o.ry ?? 0.1)
  const top = []
  for (let k = 0; k < 14; k++) {
    const a = (k / 14) * Math.PI * 2
    const j = 0.92 + r() * 0.14
    top.push([cx + Math.cos(a) * (w / 2) * j, cy + Math.sin(a) * ry * j])
  }
  const th = w * (o.band ?? 0.13)
  const depth = w * (o.depth ?? 0.42)
  const L = top[7]
  const R = top[0]
  const tip = cx + (r() - 0.5) * w * 0.3
  const j = () => (r() - 0.5) * w * 0.06
  const lo = [L[0] + w * 0.02, L[1] + th]
  const ro = [R[0] - w * 0.02, R[1] + th]
  const under = [
    L, lo,
    [cx - w * 0.36 + j(), cy + th + depth * 0.2],
    [cx - w * 0.22 + j(), cy + th + depth * 0.34],
    [cx - w * 0.14 + j(), cy + th + depth * 0.55],
    [tip - w * 0.05, cy + th + depth * 0.76],
    [tip, cy + th + depth],
    [tip + w * 0.07, cy + th + depth * 0.7],
    [cx + w * 0.18 + j(), cy + th + depth * 0.46],
    [cx + w * 0.3 + j(), cy + th + depth * 0.32],
    [cx + w * 0.4 + j(), cy + th + depth * 0.12],
    ro, R,
  ]
  const front = top.slice(0, 8).reverse()
  const body = poly([...front, ...[...under].reverse()])
  // 띠의 깎은 결(새긴 홈)과 밑면 줄, 오른쪽 그늘 빗금
  let hatch = line([[lo[0] + w * 0.06, lo[1] - 0.6], [ro[0] - w * 0.06, ro[1] - 0.6]])
  for (let k = 0; k < Math.round(w / 22); k++) {
    const x = lo[0] + w * 0.1 + ((ro[0] - lo[0] - w * 0.2) * (k + 0.5)) / Math.round(w / 22)
    hatch += line([[x, cy + ry * 0.9 + 2], [x, cy + th - 1]])
  }
  hatch += line([[cx - w * 0.2, cy + th + depth * 0.34], [cx + w * 0.22, cy + th + depth * 0.36]])
  // 그늘 쪽(오른쪽) 빗금 — 밑면 선 안에서 멈춘다
  const underAt = (x) => {
    let best = cy + th
    for (let i = 1; i < under.length - 2; i++) {
      const [ax, ay] = under[i]
      const [bx, by] = under[i + 1]
      if ((x - ax) * (x - bx) <= 0 && ax !== bx) best = Math.max(best, ay + ((by - ay) * (x - ax)) / (bx - ax))
    }
    return best
  }
  for (let k = 0; k < 6; k++) {
    const x = cx + w * (0.1 + k * 0.065)
    const yb = underAt(x) - 3
    if (yb > cy + th + 6) hatch += line([[x, cy + th + 3], [x - 0.8, yb]])
  }
  // 덩굴 — 띠 가장자리에서 늘어진 초록
  let vines = ''
  for (let k = 0; k < (o.vines ?? 3); k++) {
    const vx = lo[0] + (ro[0] - lo[0]) * (0.15 + r() * 0.7)
    const vy = cy + ry * 0.8 + th * 0.3
    const len = th * (0.6 + r() * 0.9)
    vines += `M${pt([vx - 1.6, vy])}C${pt([vx - 2.5, vy + len * 0.45])} ${pt([vx + 1.5, vy + len * 0.7])} ${pt([vx, vy + len])}C${pt([vx + 2.5, vy + len * 0.66])} ${pt([vx - 0.5, vy + len * 0.4])} ${pt([vx + 1.6, vy])}Z`
  }
  return { top, under, parts: [P('stone', body), P('hatch', hatch), P('fill', poly(top)), P('forest', vines), P('ink-bold', line(under)), P('ink', poly(top) + vines)] }
}
/** 윗면의 깎은 석회암 벽 — 낮은 벽 토막(옆모습), 윗선이 들쭉날쭉 */
function channelWall(x, y, w, h, seed) {
  const r = rng(seed)
  const top = []
  for (let i = 0; i <= 4; i++) top.push([x - w / 2 + (w * i) / 4, y - h * (0.6 + r() * 0.4)])
  const body = poly([[x - w / 2, y], ...top, [x + w / 2, y]])
  let hatch = ''
  for (let i = 1; i < 4; i++) hatch += line([[top[i][0], top[i][1] + 3], [top[i][0], y - 2]])
  // 새긴 통로 어귀 — 벽 가운데의 아치 구멍
  const aw = Math.min(8, w * 0.18)
  const arch = `M${pt([x - aw / 2, y])}V${r1(y - h * 0.4)}A${r1(aw / 2)} ${r1(aw / 2)} 0 0 1 ${pt([x + aw / 2, y - h * 0.4])}V${r1(y)}Z`
  return [P('fill', body), P('stone', body), P('hatch', hatch), P('dark', arch), P('ink', body)]
}
/** 조각에서 흘러내리는 폭포 — 가는 물줄기 둘과 끝의 물보라 (떨어지며 흩어진다) */
function falls(x, y0, y1, seed) {
  const r = rng(seed)
  const wob = (dx) => smooth([[x + dx, y0], [x + dx * 1.1 + (r() - 0.5) * 1.5, y0 + (y1 - y0) * 0.35], [x + dx * 1.25 + (r() - 0.5) * 2, y0 + (y1 - y0) * 0.7], [x + dx * 1.4 + (r() - 0.5) * 2.5, y1]])
  const body = poly([[x - 2, y0], [x + 2, y0], [x + 3.2, y1], [x - 3.2, y1]])
  let spray = ''
  for (let k = 0; k < 4; k++) {
    const sx = x + (k - 1.5) * 4 + (r() - 0.5) * 2
    const sy = y1 + 3 + r() * 8
    spray += `M${pt([sx - 2, sy])}Q${pt([sx, sy - 2])} ${pt([sx + 2, sy])}`
  }
  return [P('sea', body), P('sea-ink', wob(-1.6) + wob(1.6) + spray)]
}
