/** 짝홀 구멍 — 바깥 고리 안에 서로 겹치지 않는 구멍들을 낸다 */
const withHoles = (outer, holes) => [...outer, outer[0], ...holes.flatMap((h) => [...h, h[0], outer[0]])]
// 만 서쪽 뭍의 언덕 — 숲 자락 밑, 벼랑 빗금 띠(해안에서 90) 안쪽 (세계 지도 무라사의 가파른 구릉)
const HILLS = [[30, 352], [226, 262], [250, 318], [330, 336], [380, 330], [400, 452], [372, 556], [300, 598], [222, 650], [140, 650], [30, 640]]
// 만 머리 북서쪽의 좁은 뭍 (숲 자락과 벼랑 띠 사이)
const HILLS_N = [[560, -60], [860, -60], [800, -20], [700, 10], [620, 40], [560, 40]]
/**
 * 바닷속 harabaz 숲의 칸 — HARABAZ 의 북쪽 꼭짓점(만 머리 둘레)은 뭍 위에 있어, 그 사이를 해안선에서 바다 쪽으로 10 물린 선으로 바꾼다.
 * 만 머리 둘레의 벼랑·물가 띠에 맹그로브 풀포기가 서지 않게 (세계 지도의 harabaz 숲도 물 위에만 선다)
 */
const HARABAZ_SEA = (() => {
  const near = ([px, py]) => COAST.reduce((b, [x, y], i) => (Math.hypot(x - px, y - py) < Math.hypot(COAST[b][0] - px, COAST[b][1] - py) ? i : b), 0)
  const i0 = near(HARABAZ[3])
  const i1 = near(HARABAZ[11])
  const shore = []
  for (let i = i0; i <= i1; i++) {
    const [ax, ay] = COAST[Math.max(0, i - 1)]
    const [bx, by] = COAST[Math.min(COAST.length - 1, i + 1)]
    const l = Math.hypot(bx - ax, by - ay) || 1
    // 진행 방향 왼쪽이 땅 — 오른쪽(바다)으로 10
    shore.push([COAST[i][0] - ((by - ay) / l) * 10, COAST[i][1] + ((bx - ax) / l) * 10])
  }
  return [...HARABAZ.slice(0, 3), ...shore, ...HARABAZ.slice(12)]
})()
